INSERT OR IGNORE INTO courses (id,slug,title,description,status,published_at,created_at,updated_at) VALUES ('career-course-job-search','busca-de-emprego-organizada','Busca de emprego organizada','Escolha oportunidades com critério, acompanhe suas candidaturas e monte uma rotina de busca que caiba na sua semana. Três aulas com exercícios e plano de ação.','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z');
