INSERT OR IGNORE INTO course_modules (id,course_version_id,title,position) VALUES ('career-course-job-search-v1-m0','career-course-job-search-v1','Da oportunidade ao acompanhamento',0);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,estimated_minutes,position) VALUES ('career-course-job-search-v1-m0-l0','career-course-job-search-v1-m0','Defina seu foco e leia a vaga','[{"title":"Transforme uma intenção em critérios","text":"‘Quero trabalhar’ é um ponto de partida. Para escolher onde concentrar energia, anote funções que deseja conhecer, atividades que já consegue realizar, horários disponíveis e regiões ou formatos de trabalho possíveis. Separe o que é indispensável do que pode ser negociado.\n\nExemplo: você pode ter disponibilidade à tarde e experiência em organizar pedidos. Esses fatos ajudam a avaliar vagas de atendimento ou apoio administrativo, sem limitar sua busca a um único nome de cargo."},{"title":"Compare tarefas, requisitos e condições","text":"Leia a descrição da vaga em três partes: o que a pessoa fará, o que precisa saber e em quais condições trabalhará. Marque requisitos obrigatórios e conhecimentos desejáveis quando o anúncio fizer essa distinção. Não presuma que duas vagas com o mesmo título tenham a mesma rotina.\n\nMonte uma comparação curta: requisito / evidência que já tenho / dúvida ou aprendizado necessário. Uma evidência pode ser uma atividade escolar ou informal, desde que seja descrita com honestidade."},{"title":"Decida seu próximo passo","text":"Se a oportunidade fizer sentido, salve o anúncio, a fonte e o prazo informado. Se faltar uma informação importante, anote uma pergunta para o canal oficial do processo. Quando um requisito indispensável estiver fora do seu alcance, procure oportunidades compatíveis e escolha um aprendizado para desenvolver.\n\nPrática: selecione uma vaga e escreva duas razões concretas para se candidatar. Depois registre uma dúvida. Evite enviar candidaturas automaticamente sem entender as tarefas e condições."}]',8,0);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-job-search-v1-m0-l0-q0','career-course-job-search-v1-m0-l0','single_choice','Uma vaga pede organização de pedidos e considera desejável conhecer uma planilha. Você já organizou pedidos, mas está aprendendo planilhas. Qual é uma boa avaliação?','Compare as tarefas com evidências reais, informe seu nível de conhecimento e diferencie requisitos obrigatórios dos desejáveis. O título sozinho não explica o trabalho.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-search-v1-m0-l0-q0-o0','career-course-job-search-v1-m0-l0-q0','Dizer que domina planilhas para aumentar a chance',0,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-search-v1-m0-l0-q0-o1','career-course-job-search-v1-m0-l0-q0','Relacionar sua experiência à tarefa e informar que está aprendendo planilhas',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-search-v1-m0-l0-q0-o2','career-course-job-search-v1-m0-l0-q0','Escolher apenas pelo título da vaga e ignorar a descrição',0,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-job-search-v1-m0-l0-q1','career-course-job-search-v1-m0-l0','reflection','Escreva uma função de interesse, duas condições importantes para você e uma experiência real relacionada. Use exemplos fictícios de empresa e não inclua dados pessoais.','Confira se seus critérios são concretos: horário, atividades e deslocamento ajudam a comparar oportunidades. Sua experiência deve indicar algo que você realmente fez.',1);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,estimated_minutes,position) VALUES ('career-course-job-search-v1-m0-l1','career-course-job-search-v1-m0','Prepare a candidatura e confira a origem','[{"title":"Adapte com base em fatos","text":"Use a descrição da vaga para escolher quais experiências verdadeiras merecem destaque no currículo. Revise seu contato e prepare uma mensagem curta com a oportunidade de interesse, uma contribuição relacionada e a indicação do arquivo anexado, quando solicitado.\n\nExemplo: ‘Tenho interesse na vaga de apoio administrativo. Em um projeto escolar, organizei registros e conferi prazos. Segue meu currículo para avaliação.’ Adapte o exemplo à sua própria história e confira os anexos antes de enviar."},{"title":"Confira quem recebe suas informações","text":"Antes de compartilhar dados, verifique a origem do anúncio e procure o processo nos canais oficiais da organização. Observe o endereço do site por inteiro: um nome parecido ou um logotipo não confirmam a identidade de quem publicou. Quando houver dúvida, busque um contato oficial de forma independente.\n\nPressa para pagar, promessa de contratação garantida e pedidos de senha ou código de acesso são sinais para interromper a interação e verificar. Não publique documentos, senhas ou dados bancários em respostas de curso ou mensagens abertas."},{"title":"Faça uma conferência antes do envio","text":"Confira destinatário, título da oportunidade, arquivo correto, legibilidade e prazo. Compartilhe apenas as informações necessárias para aquela etapa pelo canal confirmado. Uma solicitação incomum merece esclarecimento antes de qualquer envio.\n\nPrática: escreva uma mensagem de candidatura sem dados pessoais e leia como se fosse a pessoa recebendo. Está claro qual vaga você busca? A experiência mencionada é verdadeira? O anexo corresponde à oportunidade?"}]',8,1);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-job-search-v1-m0-l1-q0','career-course-job-search-v1-m0-l1','multiple_choice','Você recebeu um anúncio por mensagem. Quais ações ajudam antes de enviar sua candidatura? Selecione todas as adequadas.','Conferir a origem por um canal independente e revisar os materiais reduz erros e exposição desnecessária. Senhas e códigos de acesso não fazem parte de uma candidatura.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-search-v1-m0-l1-q0-o0','career-course-job-search-v1-m0-l1-q0','Procurar a oportunidade nos canais oficiais da organização',1,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-search-v1-m0-l1-q0-o1','career-course-job-search-v1-m0-l1-q0','Conferir o destinatário e o currículo anexado',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-search-v1-m0-l1-q0-o2','career-course-job-search-v1-m0-l1-q0','Enviar senha ou código de acesso para agilizar a seleção',0,2);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-search-v1-m0-l1-q0-o3','career-course-job-search-v1-m0-l1-q0','Confiar apenas no logotipo exibido na mensagem',0,3);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-job-search-v1-m0-l1-q1','career-course-job-search-v1-m0-l1','reflection','Escreva uma mensagem curta de candidatura para uma vaga fictícia e indique uma verificação que faria antes de enviá-la. Não inclua contatos ou documentos.','A mensagem deve identificar a oportunidade e uma experiência relacionada. A verificação pode ser confirmar o canal oficial, o destinatário ou o arquivo anexado.',1);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,estimated_minutes,position) VALUES ('career-course-job-search-v1-m0-l2','career-course-job-search-v1-m0','Acompanhe candidaturas e ajuste a rotina','[{"title":"Registre para não depender da memória","text":"Após se candidatar, anote vaga, organização, data, origem, etapa e próximo passo. No seu painel, use o acompanhamento de candidaturas para manter essas informações reunidas. Se receber um prazo, registre-o; se não houver prazo, não o trate como combinado.\n\nExemplo: ‘Vaga de atendimento / enviada hoje / aguardando retorno / conferir o canal de contato na próxima revisão’. Atualize a etapa quando receber uma resposta ou decidir encerrar a candidatura."},{"title":"Organize uma rotina possível","text":"Separe pequenos períodos para procurar vagas, preparar materiais e acompanhar respostas. Escolha uma quantidade de tarefas compatível com seus horários e energia. Uma rotina sustentável é mais útil do que uma meta grande que você não consegue manter.\n\nSe o processo informar uma data de retorno, aguarde esse prazo antes de buscar atualização. Quando fizer contato, seja breve e use o canal indicado, sem enviar mensagens repetidas. Continue avaliando outras oportunidades enquanto espera."},{"title":"Aprenda com o processo","text":"Ao final da semana, revise o que você conseguiu fazer e onde encontrou dificuldade. Se lê muitas vagas e quase nenhuma combina com sua situação, ajuste os filtros. Se tem dificuldade de explicar uma experiência, reserve tempo para revisar o currículo ou praticar uma entrevista.\n\nA ausência de retorno não explica, sozinha, o motivo da decisão. Evite tirar conclusões sobre seu valor pessoal. Prática: defina uma ação pequena para a próxima semana, um horário possível e como verificará se a realizou."}]',8,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-job-search-v1-m0-l2-q0','career-course-job-search-v1-m0-l2','single_choice','A organização informou que dará retorno na próxima semana. Qual próximo passo faz sentido?','Registrar o prazo permite acompanhar com clareza. Continuar a busca e aguardar o prazo combinado evita depender de uma única candidatura ou repetir contatos sem necessidade.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-search-v1-m0-l2-q0-o0','career-course-job-search-v1-m0-l2-q0','Enviar várias mensagens por dia até receber uma resposta',0,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-search-v1-m0-l2-q0-o1','career-course-job-search-v1-m0-l2-q0','Registrar o prazo, continuar a busca e acompanhar pelo canal indicado',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-search-v1-m0-l2-q0-o2','career-course-job-search-v1-m0-l2-q0','Apagar o registro da candidatura porque ainda não houve resposta',0,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-job-search-v1-m0-l2-q1','career-course-job-search-v1-m0-l2','reflection','Monte uma pequena rotina para a próxima semana: uma ação de busca, uma de preparação e uma de acompanhamento, com horários possíveis.','Escolha ações que dependam de você, como revisar uma seção do currículo ou registrar uma candidatura. Receber uma proposta depende de outras pessoas e não é uma tarefa sob seu controle.',1);
INSERT OR IGNORE INTO courses (id,slug,title,description,status,published_at,created_at,updated_at) VALUES ('career-course-communication','comunicacao-no-trabalho','Comunicação no trabalho','Pratique escuta, mensagens claras e conversas sobre prazos e dificuldades. Três aulas com situações de trabalho, exercícios e reflexão.','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z');
INSERT OR IGNORE INTO course_versions (id,course_id,version,status,pass_score,created_at,published_at) VALUES ('career-course-communication-v1','career-course-communication',1,'published',70,'2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z');
INSERT OR IGNORE INTO course_modules (id,course_version_id,title,position) VALUES ('career-course-communication-v1-m0','career-course-communication-v1','Clareza nas conversas do dia a dia',0);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,estimated_minutes,position) VALUES ('career-course-communication-v1-m0-l0','career-course-communication-v1-m0','Escute e confirme os combinados','[{"title":"Entenda antes de responder","text":"Uma orientação pode parecer clara para quem fala e ainda deixar dúvidas para quem recebe. Ouça a tarefa completa e identifique objetivo, resultado esperado, prazo e pessoa responsável. Se algum ponto estiver faltando, peça esclarecimento com uma pergunta específica.\n\nExemplo: ao ouvir ‘organize os pedidos’, você pode perguntar se deve separar por data, por cliente ou por prioridade. Confirmar o critério evita refazer trabalho e ajuda a alinhar expectativas."},{"title":"Confirme com suas próprias palavras","text":"Depois de ouvir, resuma o que entendeu sem apenas repetir ‘certo’. Diga o que fará, até quando e qual dúvida ainda precisa resolver. Dê espaço para a outra pessoa corrigir algum detalhe.\n\nExemplo: ‘Vou conferir os pedidos de hoje e separar os que estão pendentes. Entrego a lista até as 16h. Quem pode confirmar os dois endereços incompletos?’ A confirmação conecta a tarefa a um resultado verificável."},{"title":"Registre o necessário","text":"Quando houver várias tarefas ou um combinado importante, use o canal de registro da equipe. Anote responsáveis, prazo e pendências de forma breve. Compartilhe apenas o necessário para a atividade e evite expor dados de clientes ou colegas em canais inadequados.\n\nPrática: pense em uma orientação recente e escreva uma confirmação em três partes: o que entendi, quando vou entregar e o que preciso esclarecer. Para o exercício, use uma situação fictícia sem nomes reais."}]',8,0);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-communication-v1-m0-l0-q0','career-course-communication-v1-m0-l0','single_choice','Sua colega pede: ‘Organize os pedidos para hoje’. O critério de organização não foi explicado. O que fazer?','Uma pergunta específica e a confirmação do prazo alinham o resultado esperado. Concordar sem entender pode gerar um trabalho diferente do necessário.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-communication-v1-m0-l0-q0-o0','career-course-communication-v1-m0-l0-q0','Escolher qualquer critério e evitar perguntas',0,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-communication-v1-m0-l0-q0-o1','career-course-communication-v1-m0-l0-q0','Perguntar qual critério usar e confirmar o prazo da entrega',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-communication-v1-m0-l0-q0-o2','career-course-communication-v1-m0-l0-q0','Dizer que terminou antes de começar para tranquilizar a colega',0,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-communication-v1-m0-l0-q1','career-course-communication-v1-m0-l0','reflection','Escreva uma confirmação para uma tarefa fictícia, incluindo resultado esperado, prazo e uma dúvida que precisa esclarecer.','Sua confirmação deve permitir que a outra pessoa entenda o que receberá e quando. Formule uma dúvida específica, como o formato da entrega ou a ordem de prioridade.',1);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,estimated_minutes,position) VALUES ('career-course-communication-v1-m0-l1','career-course-communication-v1-m0','Escreva mensagens que ajudam a agir','[{"title":"Dê contexto e faça um pedido claro","text":"Uma mensagem de trabalho precisa ajudar a pessoa a entender o assunto e o que fazer em seguida. Comece com o contexto necessário, apresente o pedido ou atualização e informe o prazo relevante. Evite deixar informações importantes espalhadas em muitas mensagens soltas.\n\nExemplo: ‘Estou fechando a lista de materiais da oficina. Você consegue confirmar a quantidade de cadeiras até as 14h? Preciso dessa informação para organizar a sala.’ O prazo vem acompanhado do motivo."},{"title":"Escolha canal e tom","text":"Use o canal combinado para o tipo de assunto. Uma dúvida simples pode ser resolvida por mensagem; um tema com muitos desencontros pode precisar de uma conversa, seguida de registro do combinado. Não marque tudo como urgente: explique o impacto e o prazo quando houver urgência real.\n\nLeia antes de enviar. Retire acusações e generalizações como ‘você nunca responde’. Prefira fatos observáveis: ‘Ainda não recebi a confirmação e preciso dela para fechar a lista’."},{"title":"Facilite a resposta","text":"Se precisar de uma decisão, apresente as informações essenciais e deixe claro o ponto a confirmar. Confira o destinatário, o anexo e se todas as pessoas incluídas precisam receber aquela informação. Revise palavras ambíguas e mantenha a mensagem curta o suficiente para ser compreendida.\n\nPrática: transforme ‘preciso disso logo’ em uma mensagem com assunto, pedido e prazo. Se ainda não souber o prazo, peça uma estimativa e combine o próximo contato."}]',8,1);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-communication-v1-m0-l1-q0','career-course-communication-v1-m0-l1','multiple_choice','Quais elementos tornam uma mensagem de trabalho mais clara? Selecione todas as alternativas adequadas.','Contexto, pedido específico e prazo ajudam a pessoa a agir. Acusações e urgência sem explicação dificultam a compreensão e podem aumentar o conflito.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-communication-v1-m0-l1-q0-o0','career-course-communication-v1-m0-l1-q0','Explicar brevemente o assunto e o pedido',1,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-communication-v1-m0-l1-q0-o1','career-course-communication-v1-m0-l1-q0','Informar o prazo relevante e seu motivo',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-communication-v1-m0-l1-q0-o2','career-course-communication-v1-m0-l1-q0','Dizer ‘você nunca ajuda’ para reforçar o pedido',0,2);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-communication-v1-m0-l1-q0-o3','career-course-communication-v1-m0-l1-q0','Marcar qualquer mensagem como urgente, sem explicar por quê',0,3);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-communication-v1-m0-l1-q1','career-course-communication-v1-m0-l1','reflection','Reescreva ‘preciso disso logo’ em uma mensagem sobre uma tarefa fictícia, com contexto, pedido e prazo. Não inclua dados de clientes ou colegas.','Confira se o destinatário conseguiria entender o que você precisa sem adivinhar. Use um prazo específico e explique sua relação com a atividade.',1);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,estimated_minutes,position) VALUES ('career-course-communication-v1-m0-l2','career-course-communication-v1-m0','Converse sobre dificuldades e próximos passos','[{"title":"Avise quando perceber um obstáculo","text":"Se uma dificuldade ameaçar um combinado, comunique assim que conseguir avaliar a situação. Explique o que já foi feito, o que impede a continuidade e qual apoio ou decisão precisa. Não prometa um prazo que você sabe que não conseguirá cumprir.\n\nExemplo: ‘Conferi 18 dos 20 pedidos. Faltam duas informações para concluir. Você pode indicar quem confirma esses dados? Consigo finalizar a revisão após recebê-los.’ Use números apenas quando forem verdadeiros."},{"title":"Trate o problema de forma concreta","text":"Para discutir um erro ou desencontro, descreva o fato e o impacto sem julgar a pessoa. Ouça a outra versão e verifique informações antes de concluir. Procure um próximo passo que possa ser observado, com responsável e prazo.\n\nExemplo: ‘A lista chegou sem as quantidades, então não consegui separar o material. Podemos combinar que a próxima lista traga esses números?’ Se a conversa se tornar desrespeitosa, interrompa e procure apoio pelo canal adequado da organização."},{"title":"Receba orientações e feche o combinado","text":"Ao receber uma sugestão de melhoria, peça um exemplo se a orientação estiver vaga. Resuma o ajuste que pretende fazer e confirme se ele atende à necessidade. Você pode reconhecer um erro e propor uma correção sem se diminuir ou atribuir culpa a alguém sem evidência.\n\nPrática: escolha uma dificuldade fictícia e escreva quatro pontos: fato, impacto, pedido de apoio e próximo passo. Ao final da conversa, confirme quem fará o quê e quando o resultado será revisto."}]',8,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-communication-v1-m0-l2-q0','career-course-communication-v1-m0-l2','single_choice','Você percebe que não conseguirá concluir uma tarefa no prazo porque faltam informações. Qual mensagem ajuda a equipe?','Informar o andamento e a dependência permite buscar uma solução e rever o combinado. Esconder o problema ou culpar alguém não esclarece o próximo passo.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-communication-v1-m0-l2-q0-o0','career-course-communication-v1-m0-l2-q0','Esperar o prazo acabar e não mencionar a dificuldade',0,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-communication-v1-m0-l2-q0-o1','career-course-communication-v1-m0-l2-q0','Explicar o andamento, a informação que falta e o apoio necessário',1,1);
