INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-communication-v1-m0-l2-q1','career-course-communication-v1-m0-l2','reflection','Descreva uma dificuldade fictícia usando fato, impacto, pedido de apoio e próximo passo. Evite nomes ou informações privadas de pessoas reais.','Use um fato que possa ser observado e um pedido que a outra pessoa consiga entender. O próximo passo deve indicar uma ação e como confirmar o novo combinado.',1);
